const api = $('Fantamaster Lineups').first().json;

// Support arrays and wrapped responses.
const root = Array.isArray(api)
  ? api[0]
  : Array.isArray(api.data)
    ? api.data[0]
    : (api.data ?? api);

const day = root.day;
const season = '2026-2027';

if (!Number.isInteger(day)) {
  throw new Error('Cannot determine current matchday');
}

const articles = [
  {
    type: 'avoid',
    slug: `chi-non-schierare-fantacalcio-flop-${day}-giornata-seriea-${season}`
  },
  {
    type: 'surprise',
    slug: `consigli-fantacalcio-${day}-giornata-sorprese-scommesse-${season}`
  },
  {
    type: 'top_pick',
    slug: `chi-schierare-fantacalcio-${day}-giornata-seriea-${season}-big-top`
  },
  {
    type: 'tier_gk',
    slug: `portieri-${day}-giornata-chi-schierare-al-fantacalcio-divisione-fasce-${season}`
  },
  {
    type: 'tier_def',
    slug: `difensori-${day}-giornata-chi-schierare-al-fantacalcio-la-divisione-in-fasce`
  },
  {
    type: 'tier_mid',
    slug: `centrocampisti-${day}-giornata-fantacalcio-chi-schierare-consigli-divisione-fasce-${season}`
  },
  {
    type: 'tier_fwd',
    slug: `attaccanti-${day}-giornata-fantacalcio-chi-schierare-consigli-divisione-fasce-${season}`
  },
  {
    type: 'match_advice',
    slug: `consigli-fantacalcio-chi-schierare-${day}-giornata-tutti-i-consigliati`
  }
];

return articles.map(article => ({
  json: {
    ...article,
    day,
    url: `https://www.fantamaster.it/${article.slug}/`
  }
}));

const posts = $input.all().flatMap(item =>
  Array.isArray(item.json) ? item.json : [item.json]
);

return posts
  .filter(post => post.content?.rendered)
  .map(post => ({
    json: {
      slug: post.slug,
      title: post.title?.rendered ?? '',
      html: post.content.rendered,
      url: post.link,
      published: post.date
    }
  }));

const articles = $input.all();
const output = [];
const seen = new Set();

function normalize(name) {
  return String(name ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-zA-Z0-9]/g, '')
    .toLowerCase();
}

function articleType(slug) {
  if (slug.startsWith('chi-non-schierare-')) return 'avoid';
  if (slug.includes('-sorprese-scommesse-')) return 'surprise';
  if (slug.includes('-big-top')) return 'top_pick';
  if (slug.includes('-tutti-i-consigliati')) return 'match_advice';
  if (slug.startsWith('portieri-')) return 'tier_gk';
  if (slug.startsWith('difensori-')) return 'tier_def';
  if (slug.startsWith('centrocampisti-')) return 'tier_mid';
  if (slug.startsWith('attaccanti-')) return 'tier_fwd';
  return 'unknown';
}

function add(player, flag, tier, type, article) {
  const name = String(player).trim();
  if (!name) return;

  const key = [
    article.slug,
    normalize(name),
    flag,
    tier
  ].join('|');

  if (seen.has(key)) return;
  seen.add(key);

  output.push({
  json: {
    player: name,
    player_key: normalize(name),
    flag,
    tier,
    source: type,
    url: article.url ?? null,
    slug: article.slug
  }
  });
}

// Extract TOP, SEMI TOP, or numbered tiers.
function detectTier(line) {
  const heading = line.trim().toUpperCase();

  if (heading === 'TOP') return 'top';

  if (/^SEMI[\s-]*TOP$/.test(heading)) {
    return 'semi_top';
  }

  // Supports 3^ FASCIA, 4° FASCIA, 5ª FASCIA, etc.
  const match = heading.match(
    /^(\d+)\s*(?:\^|°|º|ª|A)?\s*FASCIA$/
  );

  if (match) {
    return `tier_${Number(match[1])}`;
  }

  return null;
}

function parseTierArticle(lines, type, article) {
  let currentTier = null;
  let readingPlayers = false;
  let total = 0;

  for (const raw of lines) {
    const line = raw.trim();

    const detectedTier = detectTier(line);

    if (detectedTier) {
      currentTier = detectedTier;
      readingPlayers = false;
      continue;
    }

    if (!currentTier) continue;

    // Player bullet: * NAME, - NAME, • NAME
    const bullet = line.match(/^[*•-]\s+(.+)$/);

    if (bullet) {
      const name = bullet[1].trim();

      if (name && !/^https?:\/\//i.test(name)) {
        add(name, null, currentTier, type, article);
        readingPlayers = true;
        total++;
      }

      continue;
    }

    // Allow blank lines and image links before a list.
    if (!line || /^\[https?:\/\//i.test(line)) {
      continue;
    }

    // Stop reading players once commentary starts.
    if (readingPlayers) {
      currentTier = null;
      readingPlayers = false;
    }
  }

  return total;
}

function parseMarkedArticle(lines, type, article) {
  const flag = type === 'top_pick'
    ? 'recommended'
    : type;

  let total = 0;

  for (const raw of lines) {
    const line = raw.trim();

    if (!line.startsWith('📌')) continue;

    const name = line
      .replace(/^📌\s*/, '')
      .split('(')[0]
      .trim();

    if (name) {
      add(name, flag, null, type, article);
      total++;
    }
  }

  return total;
}

function parseMatchAdvice(lines, type, article) {
  let currentFlag = null;
  let total = 0;

  for (const raw of lines) {
    const line = raw.trim();

    // Remove formatting and heading emojis.
    const heading = line
      .replace(/^[#*\s🟢🔴💡]+/gu, '')
      .replace(/[*\s]+$/g, '')
      .toUpperCase();

    if (heading === 'CONSIGLIATI') {
      currentFlag = 'recommended';
      continue;
    }

    if (heading === 'SCONSIGLIATI') {
      currentFlag = 'avoid';
      continue;
    }

    if (heading === 'SCOMMESSE') {
      currentFlag = 'surprise';
      continue;
    }

    if (!currentFlag) continue;

    // - Player A, Player B, Player C
    const bullet = line.match(/^[-•*]\s+(.+)$/);

    if (bullet) {
      const names = bullet[1]
        .split(',')
        .map(n => n.trim())
        .filter(Boolean);

      for (const name of names) {
        add(name, currentFlag, null, type, article);
        total++;
      }

      currentFlag = null;
    }
  }

  return total;
}

// Main processing
for (const item of articles) {
  const article = item.json;
  const slug = article.slug ?? '';
  const text = article.articleText ?? '';
  const type = articleType(slug);

  if (type === 'unknown') {
    throw new Error(`Unknown article type: ${slug}`);
  }

  if (!text.trim()) {
    throw new Error(`Empty article: ${slug}`);
  }

  const lines = text.split(/\r?\n/);
  let count = 0;

  if (['avoid', 'top_pick', 'surprise'].includes(type)) {
    count = parseMarkedArticle(lines, type, article);
  } else if (type === 'match_advice') {
    count = parseMatchAdvice(lines, type, article);
  } else if (type.startsWith('tier_')) {
    count = parseTierArticle(lines, type, article);
  }

  if (count === 0) {
    throw new Error(
      `No recommendations extracted from ${slug}`
    );
  }
}

return output;

const squadData = $('Squad JSON').first().json;
const squad = squadData.data?.players ?? squadData.players;

if (!Array.isArray(squad)) {
  throw new Error('Squad players array not found');
}

// Handle both JSON arrays and n8n-wrapped responses.
function unpack(value) {
  if (typeof value === 'string') {
    value = JSON.parse(value);
  }
  if (Array.isArray(value)) {
    return value.flatMap(unpack);
  }
  if (value?.lineups) return [value];
  if (value?.data) return unpack(value.data);
  if (value?.body) return unpack(value.body);
  if (value?.json) return unpack(value.json);
  return [];
}

const documents = $input.all()
  .flatMap(item => unpack(item.json));

const matches = documents.flatMap(d => d.lineups ?? []);

if (matches.length === 0) {
  throw new Error(
    'No matches found. Check Fantamaster HTTP output.'
  );
}

const metadata = {
  matchday: documents[0]?.day ?? null,
  updated: documents[0]?.last_updated ?? null
};

function normalize(name) {
  return String(name ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-zA-Z0-9]/g, '')
    .toLowerCase();
}

function findPlayer(list, name) {
  return (list ?? []).find(
    p => normalize(p.player) === normalize(name)
  );
}

const sources = ['fm', 'sky', 'roma', 'milano'];

return squad.map(player => {
  const projections = [];
  const medical = [];

  for (const match of matches) {
    for (const side of ['home', 'away']) {
      const opponent = side === 'home'
        ? match.away
        : match.home;

      // Collect predictions from each source.
      for (const source of sources) {
        const data = match[source];
        if (!data) continue;

        for (const [field, status] of [
          ['lineup', 'starter'],
          ['bench', 'bench'],
          ['uncertain', 'uncertain']
        ]) {
          const entry = findPlayer(
            data[`${side}_${field}`],
            player.name
          );

          if (!entry) continue;

          projections.push({
            source,
            status,
            opponent,
            team: match[side],
            fixture: `${match.home} - ${match.away}`,
            date: match.date ?? null,
            probability: entry.prob ?? null,
            sources: entry.sources ?? null,
            ipa: entry.ipa ?? null,
            venue: side === 'home' ? 'home' : 'away'
          });
        }
      }

      // Collect injuries, suspensions and doubts.
      for (const [field, status] of [
        ['injured', 'injured'],
        ['banned', 'suspended'],
        ['indoubt', 'doubtful']
      ]) {
        const entry = findPlayer(
          match[`${side}_${field}`],
          player.name
        );

        if (entry) {
          medical.push({
            status,
            description: entry.desc ?? null,
            team: match[side]
          });
        }
      }
    }
  }

  // Fantamaster's own prediction is the primary one.
  const fm = projections.find(p => p.source === 'fm');

  const sourceAgreement = Object.fromEntries(
    sources.map(source => [
      source,
      projections.find(p => p.source === source)
        ?.status ?? 'not_found'
    ])
  );

  return {
    json: {
      name: player.name,
      role: player.role,
      found: projections.length > 0 || medical.length > 0,
      status: medical.some(m => m.status === 'suspended')
        ? 'suspended'
        : medical.some(m => m.status === 'injured')
        ? 'injured'
        : fm?.status ?? 'unknown',
      team: fm?.team ?? medical[0]?.team ?? null,
      opponent: fm?.opponent ?? null,
      fixture: fm?.fixture ?? null,
      probability: fm?.probability ?? null,
      venue: fm?.venue ?? null,
      sourceAgreement,
      medical,
      projections,
      ...metadata
    }
  };
});

const squadData = $('Squad JSON').first().json;
const squad = squadData.data?.players ?? squadData.players;

const lineups = $('Match Squad').all().map(i => i.json);
const editorial = $('Parse Editorial').all().map(i => i.json);

if (!Array.isArray(squad) || squad.length !== 25) {
  throw new Error('Expected 25 players in Squad JSON');
}

if (!lineups.some(p => p.name)) {
  throw new Error(
    'Match Squad output has no name field. ' +
    'Check the referenced node and its output.'
  );
}

function normalize(name) {
  return String(name ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-zA-Z0-9]/g, '')
    .toLowerCase();
}

// Support surname-initial variations.
function nameKeys(name) {
  const tokens = String(name ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9 ]/g, ' ')
    .trim()
    .split(/\s+/)
    .filter(Boolean);

  const keys = new Set([normalize(name)]);

  if (
    tokens.length === 2 &&
    (tokens[0].length === 1 || tokens[1].length === 1)
  ) {
    keys.add(normalize(tokens.slice().reverse().join('')));
  }

  return keys;
}

function samePlayer(a, b) {
  const keysA = nameKeys(a);
  const keysB = nameKeys(b);
  return [...keysA].some(key => keysB.has(key));
}

// Enrich each player from the original squad.
return squad.map(player => {
  const lineup = lineups.find(
    p => samePlayer(p.name, player.name)
  );

  const recommendations = editorial.filter(
    r => samePlayer(r.player, player.name)
  );

  const flags = [...new Set(
    recommendations.map(r => r.flag).filter(Boolean)
  )];

  const tiers = [...new Set(
    recommendations.map(r => r.tier).filter(Boolean)
  )];

  return {
    json: {
      name: player.name,
      role: player.role,

      team: lineup?.team ?? null,
      opponent: lineup?.opponent ?? null,

      status: lineup?.status ?? 'unknown',
      starter_probability: lineup?.probability ?? null,

      tier: tiers.length === 1 ? tiers[0] : null,
      flags,

      availability: lineup?.medical ?? [],

      editorial: recommendations.map(r => ({
        flag: r.flag,
        tier: r.tier,
        source: r.source,
        url: r.url
      })),

      matchday: lineup?.matchday ?? null,
      updated: lineup?.updated ?? null,
      venue: lineup?.venue ?? null
    }
  };
});

const players = $input.all().map(item => item.json);

if (players.length !== 25) {
  throw new Error(`Expected 25 players, got ${players.length}`);
}

const positions = {
  GK:  '🧤 PORTIERI',
  DEF: '🛡️ DIFENSORI',
  MID: '⚙️ CENTROCAMPISTI',
  FWD: '⚽ ATTACCANTI'
};

const flagLabels = {
  recommended: '✅ Consigliato',
  avoid: '⛔ Sconsigliato',
  surprise: '💡 Scommessa'
};

const statusLabels = {
  starter: '🟢 Titolare',
  bench: '🟠 Panchina prevista',
  uncertain: '🟡 In dubbio',
  unknown: '⚪ Da verificare',
  suspended: '⛔ Squalificato'
};

// Prevent dynamic values from breaking Telegram HTML.
function escapeHTML(value) {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function formatProbability(value) {
  if (value === null || value === undefined || value === '') {
    return 'N/D';
  }

  const number = Number(value);
  return Number.isFinite(number)
    ? `${number}%`
    : 'N/D';
}

function formatTier(tier) {
  if (!tier) return 'Fascia N/D';
  if (tier === 'top') return 'TOP';
  if (tier === 'semi_top') return 'SEMI TOP';

  const match = tier.match(/^tier_(\d+)$/);
  if (match) return `${match[1]}ª fascia`;

  return escapeHTML(tier);
}

function formatPlayer(p) {
  const name = escapeHTML(p.name);
  const probability = formatProbability(p.starter_probability);

  const injured = p.status === 'injured' ||
    (p.availability ?? []).some(a => a.status === 'injured');

  // Injured: no matchup, flags or tier.
  if (injured) {
    return `🚑 <b>${name}</b> — <b>INFORTUNATO</b>\n` +
           `    Titolarità: ${probability}`;
  }

  const status = statusLabels[p.status] ?? '⚪ Da verificare';

  const venueSymbol =
  p.venue === 'home' ? 'vs' :
  p.venue === 'away' ? '@' :
  '?';

  const matchup = p.opponent
    ? `${venueSymbol} ${escapeHTML(p.opponent)}`
    : 'Avversario N/D';

  const team = p.team
    ? `${escapeHTML(p.team)} · `
    : '';

  const tier = formatTier(p.tier);

  const flags = (p.flags ?? []).map(
    flag => flagLabels[flag] ?? escapeHTML(flag)
  );

  let text = `${status.split(' ')[0]} <b>${name}</b>` +
    ` — <b>${probability}</b> · ` +
    status.split(' ').slice(1).join(' ');

  text += `\n    🆚 ${team}${matchup} · ${tier}`;

  if (flags.length > 0) {
    text += `\n    ${flags.join(' · ')}`;
  }

  return text;
}

const matchday = players[0]?.matchday ?? 'N/D';
const updated = players[0]?.updated ?? 'N/D';

const output = [];

for (const [role, title] of Object.entries(positions)) {
  const group = players.filter(p => p.role === role);

  if (group.length === 0) continue;

  const header =
    `<b>⚽ FANTACALCIO — GIORNATA ${escapeHTML(matchday)}</b>` +
    `\n<b>${title}</b>`;

  const body = group.map(formatPlayer).join('\n\n');

  const footer =
    `\n\n<i>🕒 Aggiornato: ${escapeHTML(updated)}</i>`;

  const message = `${header}\n\n${body}${footer}`;

  if (message.length > 3900) {
    throw new Error(`Telegram message too long: ${role}`);
  }

  output.push({
    json: {
      role,
      message,
      playerCount: group.length
    }
  });
}

return output;

const raw = $input.first().json;

function unpack(value) {
  if (Array.isArray(value)) return unpack(value[0]);
  if (Array.isArray(value?.lineups)) return value;
  if (value?.data) return unpack(value.data);
  throw new Error('Fantamaster lineups not found');
}

const data = unpack(raw);

const zone = 'Europe/Rome';
const now = $now.setZone(zone);

// Italian month names
const months = {
  gennaio: 1, febbraio: 2, marzo: 3,
  aprile: 4, maggio: 5, giugno: 6,
  luglio: 7, agosto: 8, settembre: 9,
  ottobre: 10, novembre: 11, dicembre: 12
};

// Reference timestamp, useful for inferring the year.
const updated = DateTime.fromFormat(
  data.last_updated ?? '',
  'dd/MM/yyyy HH:mm',
  { zone }
);

const reference = updated.isValid ? updated : now;

function parseKickoff(dateString) {
  // Example: "sabato 21 novembre, 15:00"
  const match = String(dateString).toLowerCase().match(
    /(\d{1,2})\s+([a-zà-ÿ]+),?\s+(\d{1,2}):(\d{2})/
  );

  if (!match) {
    throw new Error(`Invalid fixture date: ${dateString}`);
  }

  const [, day, monthName, hour, minute] = match;
  const month = months[monthName];

  if (!month) {
    throw new Error(`Unknown month: ${monthName}`);
  }

  // API dates have no year.
  // Infer it relative to the API update timestamp,
  // including fixtures around New Year.
  const candidates = [
    reference.year - 1,
    reference.year,
    reference.year + 1
  ].map(year => DateTime.fromObject({
    year,
    month,
    day: Number(day),
    hour: Number(hour),
    minute: Number(minute)
  }, { zone })).filter(dt => dt.isValid);

  if (!candidates.length) {
    throw new Error(`Invalid kickoff: ${dateString}`);
  }

  candidates.sort((a, b) =>
    Math.abs(a.toMillis() - reference.toMillis()) -
    Math.abs(b.toMillis() - reference.toMillis())
  );

  return candidates[0];
}

// Find the earliest game across ALL fixtures.
const fixtures = data.lineups.map(match => ({
  home: match.home,
  away: match.away,
  kickoff: parseKickoff(match.date)
}));

if (!fixtures.length) {
  throw new Error('No fixtures returned by Fantamaster');
}

fixtures.sort((a, b) =>
  a.kickoff.toMillis() - b.kickoff.toMillis()
);

const first = fixtures[0];

const minutesUntil =
  (first.kickoff.toMillis() - now.toMillis()) / 60000;

const shouldRun =
  minutesUntil > 0 && minutesUntil <= 120;

// Generate a unique identifier for this matchday.
const seasonStart = first.kickoff.month >= 7
  ? first.kickoff.year
  : first.kickoff.year - 1;

const reportKey =
  `${seasonStart}-${seasonStart + 1}:${data.day}`;

// Preserve the original API response for downstream nodes.
return [{
  json: {
    ...data,
    automation: {
      shouldRun,
      matchday: data.day,
      reportKey,
      firstFixture: `${first.home} vs ${first.away}`,
      firstKickoff: first.kickoff.toISO(),
      now: now.toISO(),
      minutesUntilKickoff: Math.round(minutesUntil),
      apiLastUpdated: data.last_updated ?? null
    }
  }
}];

const players = $input.all().map(item => item.json);

if (players.length !== 25) {
  throw new Error(
    `Expected 25 squad players, got ${players.length}`
  );
}

const roster = players.map(p => ({
  name: p.name,
  role: p.role,
  team: p.team,
  opponent: p.opponent,
  venue: p.venue,
  status: p.status,
  starter_probability: p.starter_probability,
  tier: p.tier,
  flags: p.flags ?? [],
  availability: p.availability ?? [],
  editorial: (p.editorial ?? []).map(e => ({
    source: e.source,
    flag: e.flag,
    tier: e.tier
  }))
}));

const eligible = roster.filter(p =>
  !['injured', 'suspended'].includes(p.status) &&
  !p.availability.some(a =>
    ['injured', 'suspended'].includes(a.status)
  )
);

if (eligible.length < 11) {
  throw new Error(
    `Only ${eligible.length} non-injured/non-suspended ` +
    `players available. Cannot even select 11.`
  );
}

return [{
  json: {
    season: '2026-2027',
    matchday: players[0].matchday,
    playerCount: roster.length,
    roster,
    rosterJSON: JSON.stringify({
      season: '2026-2027',
      matchday: players[0].matchday,
      players: roster
    }, null, 2)
  }
}];

