const raw = $input.first().json;
const value = raw.output ?? raw;

const result = typeof value === 'string'
  ? JSON.parse(value)
  : value;

const formations = {
  '4-3-3': [4, 3, 3],
  '4-4-2': [4, 4, 2],
  '3-4-3': [3, 4, 3],
  '3-5-2': [3, 5, 2],
  '4-5-1': [4, 5, 1],
  '5-3-2': [5, 3, 2],
  '5-4-1': [5, 4, 1]
};

const expected = formations[result.formation];

if (!expected) {
  throw new Error('Invalid formation');
}

const roster = $('Merge Evidence')
  .all()
  .map(item => item.json);

const byName = new Map(
  roster.map(p => [p.name, p])
);

const used = new Set();

function validatePlayer(name, role) {
  const player = byName.get(name);

  if (!player) {
    throw new Error(`Unknown player: ${name}`);
  }

  if (player.role !== role) {
    throw new Error(`Invalid role: ${name} (${role})`);
  }

  if (used.has(name)) {
    throw new Error(`Duplicate player: ${name}`);
  }

  const unavailable =
    ['injured', 'suspended'].includes(player.status) ||
    (player.availability ?? []).some(a =>
      ['injured', 'suspended'].includes(a.status)
    );

  if (unavailable) {
    throw new Error(`Unavailable player selected: ${name}`);
  }

  used.add(name);
}

const required = {
  GK: 1,
  DEF: expected[0],
  MID: expected[1],
  FWD: expected[2]
};

// Validate starters by role.
for (const [role, count] of Object.entries(required)) {
  const selected = result.starters?.[role];

  if (!Array.isArray(selected) || selected.length !== count) {
    throw new Error(
      `Invalid ${role} count: expected ${count}`
    );
  }

  for (const name of selected) {
    validatePlayer(name, role);
  }
}

// Validate exactly seven ordered substitutes.
if (!Array.isArray(result.bench) ||
    result.bench.length !== 7) {
  throw new Error('Expected exactly 7 bench players');
}

for (const substitute of result.bench) {
  validatePlayer(substitute.name, substitute.role);
}

// Include backup goalkeeper if one is available.
const eligibleGoalkeepers = roster.filter(p =>
  p.role === 'GK' &&
  !['injured', 'suspended'].includes(p.status) &&
  !(p.availability ?? []).some(a =>
    ['injured', 'suspended'].includes(a.status)
  )
);

if (
  eligibleGoalkeepers.length >= 2 &&
  !result.bench.some(p => p.role === 'GK')
) {
  throw new Error('Missing backup goalkeeper');
}

if (used.size !== 18) {
  throw new Error('Expected 18 unique players');
}

return [{
  json: {
    ...result,
    validation: {
      valid: true,
      starters: 11,
      substitutes: 7
    }
  }
}];

const recommendation = $input.first().json;

const roster = $('Merge Evidence')
  .all()
  .map(item => item.json);

const byName = new Map(
  roster.map(p => [p.name, p])
);

const escapeHTML = s => String(s ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

function playerLine(name) {
  const p = byName.get(name);
  const probability = p?.starter_probability ?? 'N/D';

  return `• ${escapeHTML(name)} (${probability}%)`
    .replace('(N/D%)', '(N/D)');
}

let message =
  `<b>🧠 AI FANTACALCIO — GIORNATA ` +
  `${roster[0]?.matchday ?? 'N/D'}</b>\n` +
  `<b>Modulo consigliato: ${escapeHTML(recommendation.formation)}</b>\n\n`;

const positions = {
  GK: '🧤 PORTIERI',
  DEF: '🛡️ DIFENSORI',
  MID: '⚙️ CENTROCAMPISTI',
  FWD: '⚽ ATTACCANTI'
};

message += '<b>✅ FORMAZIONE TITOLARE</b>\n';

for (const [role, title] of Object.entries(positions)) {
  message += `\n<b>${title}</b>\n`;

  message += recommendation.starters[role]
    .map(playerLine)
    .join('\n') + '\n';
}

message += '\n<b>🔄 PANCHINA — ORDINE DI PRIORITÀ</b>\n';

recommendation.bench.forEach((p, index) => {
  message +=
    `${index + 1}. <b>${escapeHTML(p.name)}</b> ` +
    `(${escapeHTML(p.role)}) — ` +
    `${escapeHTML(p.reason)}\n`;
});

message += '\n<b>📋 ANALISI</b>\n';
message += escapeHTML(recommendation.rationale);

message += '\n\n<b>💡 POSSIBILI MODIFICHE</b>\n';

for (const tip of recommendation.tips ?? []) {
  message += `• ${escapeHTML(tip)}\n`;
}

if ((recommendation.risks ?? []).length) {
  message += '\n<b>⚠️ RISCHI</b>\n';

  for (const risk of recommendation.risks) {
    message += `• ${escapeHTML(risk)}\n`;
  }
}

if (message.length > 3900) {
  throw new Error('AI Telegram report too long');
}

return [{ json: { message } }];
